import{_ as a,c as n,a as e,o as t}from"./app-C_dHcy8Q.js";const o={};function c(i,s){return t(),n("div",null,[...s[0]||(s[0]=[e('<h1 id="ingestion-api" tabindex="-1"><a class="header-anchor" href="#ingestion-api"><span>Ingestion API</span></a></h1><p>鉴权</p><ul><li>头部：<code>X-Timestamp</code>（秒）、<code>X-Nonce</code>（随机串）、<code>X-Signature</code>（Base64(HMAC-SHA256(secret, <code>${ts}\\n${nonce}\\n${sha256(body)}</code>))）</li><li>异常码：401/403（签名）、429（限流）、400（格式错误）</li></ul><p>POST /api/ingest/events</p><ul><li>请求体：事件数组，每条至少包含 <code>event</code>、<code>ts</code>，推荐加 <code>uid</code>、<code>game_id</code>、<code>env</code></li></ul><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">[</span></span>\n<span class="line">  <span class="token punctuation">{</span><span class="token property">&quot;event&quot;</span><span class="token operator">:</span><span class="token string">&quot;session.start&quot;</span><span class="token punctuation">,</span><span class="token property">&quot;ts&quot;</span><span class="token operator">:</span><span class="token number">1731700000000</span><span class="token punctuation">,</span><span class="token property">&quot;attrs&quot;</span><span class="token operator">:</span><span class="token punctuation">{</span><span class="token property">&quot;uid&quot;</span><span class="token operator">:</span><span class="token string">&quot;u1&quot;</span><span class="token punctuation">,</span><span class="token property">&quot;game_id&quot;</span><span class="token operator">:</span><span class="token string">&quot;demo&quot;</span><span class="token punctuation">,</span><span class="token property">&quot;env&quot;</span><span class="token operator">:</span><span class="token string">&quot;dev&quot;</span><span class="token punctuation">}</span><span class="token punctuation">}</span></span>\n<span class="line"><span class="token punctuation">]</span></span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>返回：<code>{&quot;ok&quot;:true}</code> 或错误详情</li></ul><p>POST /api/ingest/payments</p><ul><li>请求体：支付事件数组（字段同上，业务字段根据需要扩展）</li></ul><h1 id="otel-collector-服务端" tabindex="-1"><a class="header-anchor" href="#otel-collector-服务端"><span>OTel Collector（服务端）</span></a></h1><ul><li>推荐直接接入 OTLP（HTTP/gRPC），采集 traces/metrics/logs</li><li>参考: ./opentelemetry-integration.md</li></ul>',11)])])}const l=a(o,[["render",c]]),r=JSON.parse('{"path":"/analytics/api-reference.html","title":"API 参考","lang":"zh-CN","frontmatter":{"title":"API 参考"},"git":{"updatedTime":1763325744000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"0ac3783c0cafbb7e76dd3fb0484cad90c77386b8","time":1763325744000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(analytics): fix unresolved links; add missing pages; harden MDX; CI link check\\\\n\\\\nfeat(analytics): add public ingestion service (cmd/analytics-ingest), Makefile targets, Dockerfiles; compose service; fix worker image\\\\n\\\\nchore(docs): adjust config to ignore node_modules in docs plugin; remove duplicate index page\\\\n\\\\nrefactor(docs): escape MDX-sensitive chars and fence YAML blocks"}]},"filePathRelative":"analytics/api-reference.md"}');export{l as comp,r as data};
